 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
            r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
            # Frames are solid rectangular outlines; their connected component bbox identifies them.
            if len(cells) >= 8 and r1-r0 >= 2 and c1-c0 >= 2:
                objs.append((color,r0,r1,c0,c1))
    if not objs:
        return [row[:] for row in grid]
    # The most internally populated frame supplies the bitmap to the others.
    def pattern_count(o):
        color,r0,r1,c0,c1=o
        return sum(grid[r][c] == color for r in range(r0+1,r1) for c in range(c0+1,c1))
    src = max(objs, key=pattern_count)
    scolor,sr0,sr1,sc0,sc1 = src
    sh,sw=sr1-sr0-1,sc1-sc0-1
    pat=[[grid[sr0+1+y][sc0+1+x] == scolor for x in range(sw)] for y in range(sh)]
    out=[row[:] for row in grid]
    for color,r0,r1,c0,c1 in objs:
        if (color,r0,r1,c0,c1)==src:
            continue
        ih,iw=r1-r0-1,c1-c0-1
        if ih < max(1, sh-1):
            for r in range(r0,r1+1):
                for c in range(c0,c1+1): out[r][c]=0
            continue
        for y in range(ih):
            for x in range(iw):
                out[r0+1+y][c0+1+x] = color if y < sh and x < sw and pat[y][x] else 0
    return out
